int main(int argc,char** argv){try{
  need(argc==3||argc==4||argc==5,"Usage: file_operations_driver OWNED_CASE_ROOT relocate|relink|removeKeep|removeDelete|rename|retarget|revert|recycle [single|multi]");const fs::path root(argv[1]);const std::string mode(argv[2]);const bool multi=argc==3||std::string_view(argv[3])=="multi";need(argc==3||multi||std::string_view(argv[3])=="single","Invalid geometry");need(root.parent_path()==fs::path("/tmp")&&root.filename().string().starts_with("biglybtc-fileops-handoff-")&&root.lexically_normal()==root,"Fresh owned /tmp/biglybtc-fileops-handoff-* case required");
  if(!fs::exists(root)){need(fs::create_directory(root),"Cannot create owned case");fs::permissions(root,fs::perms::owner_all);}struct stat rootInfo{};need(::lstat(root.c_str(),&rootInfo)==0&&S_ISDIR(rootInfo.st_mode)&&rootInfo.st_uid==::geteuid()&&(rootInfo.st_mode&077)==0&&fs::canonical(root)==root&&fs::is_empty(root),"Case root must be private, canonical, owned and empty");
  st::FileOperationKind kind;if(mode=="relocate"){kind=st::FileOperationKind::Relocate;}else if(mode=="relink"){kind=st::FileOperationKind::Relink;}else if(mode=="removeKeep"){kind=st::FileOperationKind::RemoveKeepData;}else if(mode=="removeDelete"){kind=st::FileOperationKind::RemoveDeleteData;}else if(mode=="rename"){kind=st::FileOperationKind::MoveFile;}else if(mode=="retarget"){kind=st::FileOperationKind::RetargetFile;}else if(mode=="revert"){kind=st::FileOperationKind::RevertFile;}else if(mode=="replace"){kind=st::FileOperationKind::ReplaceFile;}else{need(mode=="recycle","Invalid operation");kind=st::FileOperationKind::RemoveRecycleData;}
  const std::string format=argc==5?argv[4]:"v1";need(format=="v1"||format=="v2"||format=="hybrid-v1"||format=="hybrid-v2","Invalid explicit format");need(format=="v1"||multi,"Versioned mutation fixtures use two nonempty files; no original empty-first relabel");
  const auto profile=root/"profile",source=root/"source",destination=root/"destination";fs::create_directories(destination);auto selected=format=="v1"?makeRecord(profile,source,root/"archives",multi?"Bundle-数据":"file-α.bin",multi,17):makeVersionedRecord(profile,source,root/"archives",format);auto survivor=makeRecord(profile,root/"survivor",root/"archives","survivor.bin",false,29);
  const auto rawHash=[](const core::TorrentHash& hash){const auto bytes=hash.bytes();return std::string(reinterpret_cast<const char*>(bytes.data()),bytes.size());};
  const auto inventory="d9:downloadsl"+selected.row+survivor.row+"e10:pause_datald4:hash"+b(rawHash(selected.hash))+"5:forcei0eed4:hash"+b(rawHash(survivor.hash))+"5:forcei0eee21:unknown.future.pluginli7e3:rawee";
  write(profile/"downloads.config",inventory);static_cast<void>(document(inventory));write(root/"before-downloads.config",inventory);write(root/"before-target.dat",selected.state);write(root/"before-survivor.dat",survivor.state);
  if(kind==st::FileOperationKind::Relink){for(std::size_t i=0;i<selected.files.size();++i){if(!selected.padding.empty()&&selected.padding[i]) continue;write(destination/selected.files[i].lexically_relative(source),selected.contents[i]);}}
  const bool oneFile=kind==st::FileOperationKind::MoveFile||kind==st::FileOperationKind::RetargetFile||kind==st::FileOperationKind::RevertFile||kind==st::FileOperationKind::ReplaceFile;
  const bool extended=oneFile||kind==st::FileOperationKind::RemoveRecycleData;
  if(kind==st::FileOperationKind::RevertFile){
    auto lease=take(st::ProfileLease::acquire(profile));st::FileOperationRequest initial{selected.hash,st::FileOperationKind::MoveFile,{}};initial.fileIndex=0;initial.fileDestination=destination/"prior-linked.bin";
    auto plan=take(st::prepareFileOperation(lease,initial));auto confirmation=take(st::confirmFileOperation(plan,plan.preview().approvalScopeDigest,false));take(st::applyFileOperation(lease,std::move(plan),confirmation));selected.files[0]=*initial.fileDestination;
    selected.state=read(profile/"active"/(selected.hash.hex()+".dat"));write(root/"before-downloads.config",read(profile/"downloads.config"));write(root/"before-target.dat",selected.state);
  }
  if(kind==st::FileOperationKind::RetargetFile){write(destination/"existing-数据.bin",selected.contents[0]);}
  if(kind==st::FileOperationKind::ReplaceFile){write(destination/"renamed-数据.bin","prior destination");write(root/"expected-prior.bin",read(destination/"renamed-数据.bin"));}
  std::string receipt;
  {
    auto lease=take(st::ProfileLease::acquire(profile));st::FileOperationRequest request{selected.hash,kind,kind==st::FileOperationKind::Relocate||kind==st::FileOperationKind::Relink?std::optional<fs::path>(destination):std::nullopt};
    if(oneFile){request.fileIndex=0;if(kind!=st::FileOperationKind::RevertFile){request.fileDestination=destination/(kind==st::FileOperationKind::RetargetFile?"existing-数据.bin":"renamed-数据.bin");}}
    if(kind==st::FileOperationKind::RemoveRecycleData){request.trashRoot=root/"data/Trash";}
    auto plan=take(st::prepareFileOperation(lease,request));
    const auto& preview=plan.preview();receipt="{\n\"schema\":"+std::to_string(format!="v1"?3:extended?2:1)+",\"mode\":"+jsonQuoted(mode)+",\"geometry\":"+jsonQuoted(multi?"multi":"single")+",\"profile\":"+jsonQuoted(profile.string())+",\"targetHash\":"+jsonQuoted(selected.hash.hex())+",\"survivorHash\":"+jsonQuoted(survivor.hash.hex())+",\"sourceRoot\":"+jsonQuoted(preview.sourceRoot.string())+",\"targetRoot\":"+jsonQuoted(preview.targetRoot.string())+",\"approvalScopeDigest\":"+jsonQuoted(preview.approvalScopeDigest)+selected.versionedFields+",\"files\":[";
    if(preview.replacement){struct stat prior{};need(::stat(request.fileDestination->c_str(),&prior)==0,"Observed actual prior destination");receipt.insert(receipt.rfind(",\"files\":["),",\"preimage\":"+jsonQuoted(preview.replacement->path.string())+",\"priorExpected\":"+jsonQuoted((root/"expected-prior.bin").string())+",\"priorDevice\":"+jsonQuoted(std::to_string(prior.st_dev))+",\"priorInode\":"+jsonQuoted(std::to_string(prior.st_ino)));}
    auto receiptFiles=preview.files;
    if(oneFile){receiptFiles.clear();for(std::size_t i=0;i<selected.files.size();++i){if(!selected.padding.empty()&&selected.padding[i]) continue;st::FileOperationEntry file;file.index=i;file.source=selected.files[i];file.destination=selected.files[i];file.actualBytes=selected.contents[i].size();file.present=true;struct stat stamp{};need(::stat(file.source.c_str(),&stamp)==0,"Missing generated pre-operation file");file.device=stamp.st_dev;file.inode=stamp.st_ino;if(i==0){file.destination=preview.files.front().destination;}receiptFiles.push_back(std::move(file));}}
    for(std::size_t i=0;i<receiptFiles.size();++i){const auto& file=receiptFiles[i];const auto expected=root/"expected"/(std::to_string(file.index)+".bin");write(expected,selected.contents[file.index]);if(i){receipt+=',';}receipt+="{\"index\":"+std::to_string(file.index)+",\"source\":"+jsonQuoted(file.source.string())+",\"destination\":"+jsonQuoted(file.destination.string())+",\"bytes\":"+std::to_string(file.actualBytes)+",\"sha256\":"+jsonQuoted(digest(selected.contents[file.index],EVP_sha256(),true))+",\"expected\":"+jsonQuoted(expected.string())+",\"device\":"+jsonQuoted(std::to_string(file.device))+",\"inode\":"+jsonQuoted(std::to_string(file.inode))+'}';}
    auto confirmation=take(st::confirmFileOperation(plan,preview.approvalScopeDigest,true));const auto result=take(st::applyFileOperation(lease,std::move(plan),confirmation));need(!st::hasPendingFileOperation(lease),"Successful operation retained a journal");receipt+="],\"moved\":"+std::to_string(result.filesMoved)+",\"deleted\":"+std::to_string(result.filesDeleted)+(extended?",\"recycled\":"+std::to_string(result.filesRecycled):std::string{})+"}\n";
  }
  write(root/"result.json",receipt);std::cout<<receipt;return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}}
